<?php
namespace App\Http\Controllers;use App\Contracts\ProtectedMediaStorage;use App\Jobs\GenerateMediaExport;use App\Models\{Group,MediaExport,Photo};use App\Services\Media\CloudFrontUrlSigner;use Illuminate\Http\Request;use Illuminate\Support\Facades\{Gate,Storage};use Illuminate\Support\Str;
class MediaExportController extends Controller {public function store(Request$r,Group$group){Gate::authorize('view',$group);$ids=$r->validate(['photo_ids'=>'required|array|max:500','photo_ids.*'=>'integer'])['photo_ids'];$authorized=[];foreach(Photo::where('group_id',$group->id)->whereIn('id',$ids)->get()as$p)if(Gate::forUser($r->user())->allows('view',$p))$authorized[]=$p->id;abort_if(!$authorized,403);$export=MediaExport::create(['uuid'=>(string)Str::uuid(),'group_id'=>$group->id,'user_id'=>$r->user()->id,'state'=>'queued','photo_ids'=>$authorized]);GenerateMediaExport::dispatch($export->id);return response()->json(['uuid'=>$export->uuid,'state'=>'queued'],202);}private function allow(Request$r,MediaExport$e):void{abort_unless($e->user_id===$r->user()->id,403);}public function show(Request$r,MediaExport$export){$this->allow($r,$export);return response()->json($export);}public function cancel(Request$r,MediaExport$export){$this->allow($r,$export);abort_if($export->state==='completed',409);$export->update(['state'=>'cancelled','cancelled_at'=>now()]);return response()->json(['state'=>'cancelled']);}public function download(Request$r,MediaExport$export,ProtectedMediaStorage$storage,CloudFrontUrlSigner$signer){$this->allow($r,$export);abort_unless($export->state==='completed'&&$export->expires_at?->isFuture(),410);if(config('media.delivery_driver')==='cloudfront')return redirect()->away($signer->sign($export->object_key,now()->addMinutes(5)));$stream=$storage->readStream($export->object_key);return response()->streamDownload(function()use($stream){fpassthru($stream);fclose($stream);},'lenspic-export.zip',['Content-Type'=>'application/zip','Cache-Control'=>'no-store, private']);}}
